(() => {
  const panels=[...document.querySelectorAll('[data-updates]')]; if(!panels.length)return;
  const allowed=['gst.gov.in','incometax.gov.in','icai.org','rbi.org.in'];
  const safeUrl=value=>{try{const u=new URL(value);return u.protocol==='https:'&&allowed.some(d=>u.hostname===d||u.hostname.endsWith('.'+d))?u.href:null}catch{return null}};
  const date=value=>value?new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Kolkata'}).format(new Date(value+'T00:00:00Z')):'Date not supplied';
  const checked=value=>value?new Intl.DateTimeFormat('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'}).format(new Date(value))+' IST':'Not available';
  const element=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el};
  let data=null,inFlight=null,offline=false;
  const states=panels.map(root=>({root,category:'all',query:'',compact:root.dataset.compact==='true'}));
  function render(state){const {root,compact,category,query}=state,list=root.querySelector('[data-feed-list]');if(!data)return;
    let items=(data.items||[]).filter(x=>safeUrl(x.url)&&(category==='all'||x.source===category)&&x.title.toLowerCase().includes(query));
    if(compact&&category==='all'){const heads=['gst','income-tax','icai','rbi'].map(id=>items.find(x=>x.source===id)).filter(Boolean).sort((a,b)=>(b.publishedAt||'').localeCompare(a.publishedAt||''));const ids=new Set(heads.map(x=>x.id));items=[...heads,...items.filter(x=>!ids.has(x.id))];}
    const total=items.length;items=items.slice(0,compact?12:60);const fragment=document.createDocumentFragment();
    for(const item of items){const a=element('a','news-item');a.href=safeUrl(item.url);a.target='_blank';a.rel='noopener noreferrer';const top=element('div','news-meta');top.append(element('span','category-badge '+item.source,item.category));const time=element('time','',date(item.publishedAt));if(item.publishedAt)time.dateTime=item.publishedAt;top.append(time);const status=data.sources.find(s=>s.id===item.source)?.status;if(offline||status!=='ok')top.append(element('span','cached-label','Saved copy'));a.append(top,element('h3','',item.title),element('span','news-source','Read official announcement'));a.append(element('span','sr-only',' (opens in a new tab)'));fragment.append(a);}
    if(!items.length){const empty=element('div','feed-empty');empty.append(element('h3','','No matching announcements'),element('p','','Try another category or search term. Official portals remain available below.'));fragment.append(empty);}
    list.replaceChildren(fragment);list.setAttribute('aria-busy','false');const count=root.querySelector('[data-result-count]');if(count)count.textContent=total+' announcement'+(total===1?'':'s');
    const bad=data.sources.filter(s=>s.status!=='ok');const status=root.querySelector('[data-feed-status]');status.textContent=offline?'Live connection unavailable. Showing saved announcements with their last-checked times.':bad.length?`${bad.map(s=>s.label).join(', ')} temporarily unavailable. Saved items are labelled.`:'Official sources checked '+checked(data.fetchedAt);status.classList.toggle('has-error',offline||bad.length>0);
    const health=root.querySelector('[data-source-health]');if(health){health.replaceChildren();data.sources.forEach(s=>{const row=element('div','source-row');const a=element('a','',s.label);a.href=safeUrl(s.url);a.target='_blank';a.rel='noopener noreferrer';row.append(a,element('span','',offline?'Saved copy':s.status==='ok'?'Connected':s.status==='stale'?'Saved copy':'Unavailable'),element('time','','Last checked: '+checked(s.checkedAt)));health.append(row);});}
  }
  async function load(){if(inFlight)return inFlight;panels.forEach(root=>{root.classList.add('is-loading');root.querySelector('[data-refresh]').disabled=true;root.querySelector('[data-feed-list]').setAttribute('aria-busy','true')});
    inFlight=(async()=>{try{const response=await fetch('/api/announcements',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error();const next=await response.json();if(!Array.isArray(next.items)||!Array.isArray(next.sources))throw Error();data=next;offline=false;}catch{offline=true;if(!data){try{const response=await fetch('/assets/announcements-snapshot.json');if(!response.ok)throw Error();data=await response.json();}catch{panels.forEach(root=>{root.querySelector('[data-feed-list]').replaceChildren(element('p','feed-empty','Announcements could not be loaded. Visit the official portals below or try refreshing.'));root.querySelector('[data-feed-status]').textContent='Connection unavailable.';});}}}
      states.forEach(render);const headline=document.querySelector('[data-latest-headline]');if(headline&&data?.items?.length){const item=data.items.find(x=>x.source==='gst'||x.source==='income-tax');if(item){headline.textContent=item.category+' — '+item.title;headline.href=safeUrl(item.url);headline.target='_blank';headline.rel='noopener noreferrer';}}
    })().finally(()=>{panels.forEach(root=>{root.classList.remove('is-loading');root.querySelector('[data-refresh]').disabled=false;root.querySelector('[data-feed-list]').setAttribute('aria-busy','false')});inFlight=null});return inFlight;
  }
  states.forEach(state=>{state.root.querySelectorAll('[data-category]').forEach(button=>button.addEventListener('click',()=>{state.category=button.dataset.category;state.root.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));render(state);state.root.querySelector('[data-feed-list]').scrollTop=0;}));state.root.querySelector('[data-search]')?.addEventListener('input',e=>{state.query=e.target.value.trim().toLowerCase();render(state)});state.root.querySelector('[data-refresh]').addEventListener('click',load)});
  load();setInterval(()=>{if(!document.hidden)load()},15*60*1000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&data&&Date.now()-Date.parse(data.fetchedAt)>15*60*1000)load()});
})();
